func (a *Agent) groundedAnswer(ctx context.Context, model anthropic.Model, query string, hits []ragcore.Hit) (GroundedReply, error) {
    // …
		sys += "\nОтдельно даётся КОНТЕКСТ ПРОЕКТА — актуальное состояние репозитория, полученное " +
			"прямым вызовом git. Используй его для ответов о текущем состоянии (ветка, файлы, изменения), " +
			"но НЕ добавляй его в sources и НЕ цитируй в quotes: у него нет chunk_id. " +
			"Документация в чанках описывает, как проект устроен; контекст проекта — что в нём происходит сейчас."
		user += "\n\nКОНТЕКСТ ПРОЕКТА (живой git, не цитировать):\n" + a.projCtx
	}

	params := anthropic.MessageNewParams{
		Model: model, MaxTokens: 1024,
		System:   []anthropic.TextBlockParam{{Text: sys}},
		Messages: []anthropic.MessageParam{anthropic.NewUserMessage(anthropic.NewTextBlock(user))},
	}
	msg, err := a.client.Messages.New(ctx, params)
	if err != nil {
		return GroundedReply{}, err
