// buildGroundedContext — контекст с chunk_id/source/section, чтобы модель могла цитировать.
func buildGroundedContext(hits []ragcore.Hit) string {
	// День 31: /help может отвечать вообще без чанков — когда вопрос про ЖИВОЕ
	// состояние проекта («какая ветка?»), а в документации релевантного нет.
	// В днях 24–25 сюда с пустыми hits не приходили (порог отсекал раньше).
	if len(hits) == 0 {
		return "(в документации нет релевантных фрагментов)"
	}
	var b strings.Builder
	for i, h := range hits {
		fmt.Fprintf(&b, "[%d] chunk_id=%s · source=%s · section=%s\n%s\n\n",
			i+1, h.Chunk.ID, h.Chunk.Source, h.Chunk.Section, strings.TrimSpace(h.Chunk.Text))
	}
	return strings.TrimRight(b.String(), "\n")
}

// parseGrounded вытаскивает JSON-объект ответа (терпит ```-обёртки и текст вокруг).
func parseGrounded(s string) (GroundedReply, bool) {
	i, j := strings.IndexByte(s, '{'), strings.LastIndexByte(s, '}')
	if i < 0 || j <= i {
		return GroundedReply{}, false
	}
	var raw struct {
		Answer  string     `json:"answer"`
		Sources []Citation `json:"sources"`
		Quotes  []Quote    `json:"quotes"`
	}
	if err := json.Unmarshal([]byte(s[i:j+1]), &raw); err != nil {
		return GroundedReply{}, false
	}
	return GroundedReply{Answer: raw.Answer, Sources: raw.Sources, Quotes: raw.Quotes}, true
}

// reLatexCmd — команды LaTeX (\emph, \tilde, \mathbb и т.п.); reNonWord — всё, кроме букв/цифр.
var (
	reLatexCmd = regexp.MustCompile(`\\[a-zA-Z]+`)
	reNonWord  = regexp.MustCompile(`[^\p{L}\p{N}]+`)
)

// normForMatch приводит текст к «словесному скелету»: нижний регистр, без LaTeX-команд,
// без пунктуации/математики/разметки — остаются только слова через один пробел. Это
// устраняет ложные ✗, когда модель скопировала фрагмент дословно, но иначе оформила
// юникод/пробелы/символы (\emph{}, ~$X$, L_2, ⟨w,x⟩ и т.п.).
func normForMatch(s string) string {
	s = strings.ToLower(s)
	s = reLatexCmd.ReplaceAllString(s, " ")
	s = reNonWord.ReplaceAllString(s, " ")
	return strings.Join(strings.Fields(s), " ")
}

// verifyQuotes размечает каждую цитату по трём уровням достоверности:
//
//	exact   — «скелет» цитаты дословно встречается в тексте чанка (подстрока);
//	partial — не дословно, но ≥85% слов цитаты присутствуют в ОДНОМ чанке
//	          (склейка/перестановка/пропуск слова — фрагмент из источника, но не буквально);
//	none    — ни того, ни другого (вероятная выдумка/пересказ своими словами).
//
// Это градация faithfulness: строгий exact не смягчается (0 ложных «дословно»),
// а честная склейка получает partial вместо клейма none.
func verifyQuotes(rep *GroundedReply, hits []ragcore.Hit) {
	skeletons := make([]string, len(hits))
	wordsets := make([]map[string]bool, len(hits))
	for i, h := range hits {
		sk := normForMatch(h.Chunk.Text)
		skeletons[i] = sk
		wordsets[i] = toWordSet(sk)
	}
	for k := range rep.Quotes {
		q := normForMatch(rep.Quotes[k].Text)
		if len([]rune(q)) < 15 {
			rep.Quotes[k].Match = "none"
			continue
		}
		rep.Quotes[k].Match = matchLevel(q, skeletons, wordsets)
	}
}

// matchLevel: exact (подстрока) → partial (≥85% слов в одном чанке) → none.
func matchLevel(q string, skeletons []string, wordsets []map[string]bool) string {
	for _, sk := range skeletons {
		if strings.Contains(sk, q) {
			return "exact"
		}
	}
	qw := strings.Fields(q)
	if len(qw) == 0 {
		return "none"
	}
	best := 0.0
	for _, ws := range wordsets {
		hit := 0
		for _, w := range qw {
			if ws[w] {
				hit++
			}
		}
		if cov := float64(hit) / float64(len(qw)); cov > best {
			best = cov
		}
	}
	if best >= 0.85 {
		return "partial"
	}
	return "none"
}

func toWordSet(skeleton string) map[string]bool {
	m := map[string]bool{}
	for _, w := range strings.Fields(skeleton) {
		m[w] = true
	}
	return m
}

// matchCounts — сколько цитат каждого уровня (exact/partial/none).
func matchCounts(qs []Quote) (exact, partial, none int) {
	for _, q := range qs {
		switch q.Match {
		case "exact":
			exact++
		case "partial":
			partial++
		default:
			none++
		}
	}
	return
}

// genResult — итог одной генерации (единообразно для облака и локали).
type genResult struct {
	answer    string
	outTokens int64
	wall      time.Duration
	idk       bool
}

func (g genResult) tokPerSec() float64 {
	if g.wall <= 0 || g.outTokens <= 0 {
		return 0
	}
	return float64(g.outTokens) / g.wall.Seconds()
}

// ragGenerate строит заземлённый промпт (тот же, что в дне 26) и генерирует ответ
// заданным бэкендом, замеряя wall-время. Промпт и контекст идентичны для обоих
// бэкендов — сравнение честное.
func ragGenerate(ctx context.Context, gen Completer, query string, hits []ragcore.Hit) (genResult, error) {
	prompt := buildLocalRAGPrompt(query, hits) // groundedSystem + buildContext — из дня 26
	start := time.Now()
	text, u, err := gen.Complete(ctx, groundedSystem, []Msg{{Role: roleUser, Text: prompt}}, CompleteOpts{MaxTokens: 400})
	wall := time.Since(start)
	if err != nil {
		return genResult{}, err
	}
	return genResult{answer: text, outTokens: u.Output, wall: wall, idk: looksLikeIDK(text)}, nil
}

// looksLikeIDK — грубая эвристика «модель ушла в не знаю».
func looksLikeIDK(s string) bool {
	l := strings.ToLower(s)
	return strings.Contains(l, "не нашёл") || strings.Contains(l, "не нашел") ||
		strings.Contains(l, "не знаю") || strings.Contains(l, "нет в базе") ||
		strings.Contains(l, "в базе знаний")
}

// judgeGrounded — опциональный облачный судья: оценивает 1–5, насколько ОТВЕТ
// опирается только на КОНТЕКСТ и отвечает на ВОПРОС. Возвращает (0,"") при ошибке.
func judgeGrounded(ctx context.Context, judge Completer, query, contextText, answer string) (int, string) {
	sys := "Ты строгий оценщик заземлённости. Оцени, насколько ОТВЕТ опирается ТОЛЬКО на КОНТЕКСТ и " +
		"по существу отвечает на ВОПРОС. Ответь СТРОГО:\nSCORE: <целое 1-5>\nNOTE: <кратко>"
	user := fmt.Sprintf("ВОПРОС: %s\n\nКОНТЕКСТ:\n%s\n\nОТВЕТ:\n%s", query, contextText, answer)
	out, _, err := judge.Complete(ctx, sys, []Msg{{Role: roleUser, Text: user}}, CompleteOpts{MaxTokens: 120})
	if err != nil {
		return 0, ""
	}
	return parseScore(out)
}

func parseScore(s string) (int, string) {
	score, note := 0, ""
	for _, ln := range strings.Split(s, "\n") {
		t := strings.TrimSpace(ln)
		if strings.HasPrefix(strings.ToUpper(t), "SCORE:") {
			for _, r := range t {
				if r >= '1' && r <= '5' {
					score = int(r - '0')
					break
				}
			}
		} else if strings.HasPrefix(strings.ToUpper(t), "NOTE:") {
			note = strings.TrimSpace(t[len("NOTE:"):])
		}
	}
	return score, note
}

// stability гоняет один и тот же вопрос K раз на ЛОКАЛИ и считает разброс.
func stability(ctx context.Context, local Completer, query string, hits []ragcore.Hit, k int) (stabReport, error) {
	var walls []time.Duration
	var toks []float64
	var answers []string
	rep := stabReport{runs: k}
	for i := 0; i < k; i++ {
		r, err := ragGenerate(ctx, local, query, hits)
		if err != nil {
			return rep, err
		}
		walls = append(walls, r.wall)
		toks = append(toks, float64(r.outTokens))
		answers = append(answers, r.answer)
		if r.idk {
			rep.idkFlips++
		}
	}
	rep.minWall, rep.maxWall, rep.avgWall = minMaxAvg(walls)
	rep.meanTokens, rep.sdTokens = meanSD(toks)
	rep.meanJaccard = meanPairwiseJaccard(answers)
	return rep, nil
}

