func idkTag(idk bool) string {
	if idk {
		return " · ⚠ «не знаю»"
	}
	return ""
}

func idkFlipTag(flips, runs int) string {
	if flips == 0 {
		return ""
	}
	return fmt.Sprintf(" · ⚠ «не знаю» в %d/%d", flips, runs)
}

func speedVerdict(local, cloud time.Duration) string {
	if local <= 0 || cloud <= 0 {
		return "—"
	}
	if cloud <= local {
		return fmt.Sprintf("облако быстрее ×%.1f", float64(local)/float64(cloud))
	}
	return fmt.Sprintf("локаль быстрее ×%.1f", float64(cloud)/float64(local))
}

func minMaxAvg(ds []time.Duration) (mn, mx, avg time.Duration) {
	if len(ds) == 0 {
		return
	}
	mn, mx = ds[0], ds[0]
	var sum time.Duration
	for _, d := range ds {
		if d < mn {
			mn = d
		}
		if d > mx {
			mx = d
		}
		sum += d
	}
	return mn, mx, sum / time.Duration(len(ds))
}

func meanSD(xs []float64) (mean, sd float64) {
	if len(xs) == 0 {
		return
	}
	for _, x := range xs {
		mean += x
	}
	mean /= float64(len(xs))
	for _, x := range xs {
		sd += (x - mean) * (x - mean)
	}
	return mean, math.Sqrt(sd / float64(len(xs)))
}

// meanPairwiseJaccard — средняя попарная близость ответов по множествам слов
// (1.0 = ответы идентичны лексически, 0 = не пересекаются). Прокси стабильности.
func meanPairwiseJaccard(texts []string) float64 {
	if len(texts) < 2 {
		return 1.0
	}
	sets := make([]map[string]bool, len(texts))
	for i, t := range texts {
		sets[i] = wordSet(t)
	}
	var sum float64
	var n int
	for i := 0; i < len(sets); i++ {
		for j := i + 1; j < len(sets); j++ {
			sum += jaccard(sets[i], sets[j])
			n++
		}
	}
	if n == 0 {
		return 1.0
	}
	return sum / float64(n)
}

func wordSet(t string) map[string]bool {
	m := map[string]bool{}
	for _, w := range strings.Fields(strings.ToLower(t)) {
		w = strings.Trim(w, ".,;:!?()[]«»\"'—-")
		if len([]rune(w)) >= 3 {
			m[w] = true
		}
	}
	return m
}

func jaccard(a, b map[string]bool) float64 {
	if len(a) == 0 && len(b) == 0 {
		return 1.0
	}
	inter := 0
	for w := range a {
		if b[w] {
			inter++
		}
	}
	union := len(a) + len(b) - inter
	if union == 0 {
		return 0
	}
	return float64(inter) / float64(union)
}

import (
	"context"

	"github.com/anthropics/anthropic-sdk-go"
)

// Msg — одно сообщение диалога, независимое от бэкенда (роль + текст).
type Msg struct {
	Role string // roleUser | roleAssistant
	Text string
}

// GenUsage — расход токенов одного вызова (у облака — из ответа API; у локали —
// из счётчиков Ollama). Названо GenUsage, чтобы не путать с anthropic.Usage.
type GenUsage struct {
	Input  int64
	Output int64
}

// CompleteOpts — параметры вызова (общие для обоих бэкендов). 0 = дефолт бэкенда.
type CompleteOpts struct {
	MaxTokens   int64
	Temperature float64
	NumCtx      int // день 29: контекстное окно локальной модели (0 = дефолт; облако игнорирует)
}

// Completer — сменный генератор текста. Одна реализация ходит в облако (Anthropic),
// другая — в локальную модель (Ollama). Вход/выход одинаковы, поэтому вызывающий код
// (chat, swarm, enforce) не знает и не должен знать, какой бэкенд под ним.
type Completer interface {
	Complete(ctx context.Context, system string, msgs []Msg, opt CompleteOpts) (string, GenUsage, error)
	Name() string
}

type cloudCompleter struct {
	client anthropic.Client
	model  anthropic.Model
}

func newCloudCompleter(client anthropic.Client, model anthropic.Model) *cloudCompleter {
	return &cloudCompleter{client: client, model: model}
}

func (c *cloudCompleter) Complete(ctx context.Context, system string, msgs []Msg, opt CompleteOpts) (string, GenUsage, error) {
	maxTok := opt.MaxTokens
	if maxTok <= 0 {
		maxTok = 700
	}
	params := anthropic.MessageNewParams{
		Model:     c.model,
		MaxTokens: maxTok,
		System:    []anthropic.TextBlockParam{{Text: system}},
		Messages:  toAnthropicMessages(msgs),
	}
	if opt.Temperature > 0 {
		params.Temperature = anthropic.Float(opt.Temperature)
	}
	msg, err := c.client.Messages.New(ctx, params)
	if err != nil {
		return "", GenUsage{}, err
	}
	return collectText(msg), GenUsage{Input: msg.Usage.InputTokens, Output: msg.Usage.OutputTokens}, nil
}

// toAnthropicMessages переводит бэкенд-независимые Msg в сообщения SDK.
func toAnthropicMessages(msgs []Msg) []anthropic.MessageParam {
	out := make([]anthropic.MessageParam, 0, len(msgs))
	for _, m := range msgs {
		if m.Role == roleAssistant {
			out = append(out, anthropic.NewAssistantMessage(anthropic.NewTextBlock(m.Text)))
		} else {
			out = append(out, anthropic.NewUserMessage(anthropic.NewTextBlock(m.Text)))
		}
	}
	return out
}

type localCompleter struct {
	llm *LocalLLM
}

func (c *localCompleter) Complete(ctx context.Context, system string, msgs []Msg, opt CompleteOpts) (string, GenUsage, error) {
	// Переносим потолок токенов/температуру запроса на клиент локальной модели.
	if opt.MaxTokens > 0 {
		c.llm.NumPredict = int(opt.MaxTokens)
	}
	if opt.Temperature > 0 {
		c.llm.Temp = opt.Temperature
	}
	if opt.NumCtx > 0 {
		c.llm.NumCtx = opt.NumCtx
	}
	// Ollama /api/chat хочет (system, история, последний user). Последнее сообщение —
	// текущий ход пользователя, предыдущие — история.
	history, user := splitLastUser(msgs)
	text, stats, err := c.llm.Chat(ctx, system, history, user)
	if err != nil {
		return "", GenUsage{}, err
	}
	return text, GenUsage{Input: int64(stats.PromptTokens), Output: int64(stats.EvalTokens)}, nil
}

// splitLastUser делит сообщения на историю (все, кроме последнего) и текст последнего
// пользовательского хода. Роли конвертируются в формат Ollama ("user"/"assistant").
func splitLastUser(msgs []Msg) ([]chatMsg, string) {
	if len(msgs) == 0 {
		return nil, ""
	}
	last := msgs[len(msgs)-1]
	hist := make([]chatMsg, 0, len(msgs)-1)
	for _, m := range msgs[:len(msgs)-1] {
		role := "user"
		if m.Role == roleAssistant {
			role = "assistant"
		}
		hist = append(hist, chatMsg{Role: role, Content: m.Text})
	}
	return hist, last.Text
}

import (
	"context"
	"fmt"
	"strings"
)

// Verdict — результат проверки запроса на конфликт с инвариантами.
type Verdict struct {
	Allowed  bool
	Violated []string // id/описания нарушенных
	Reason   string   // объяснение отказа
	ByCode   bool     // сработала детерминированная проверка
	Decision string   // сырой DECISION от LLM-проверяющего (ALLOW/DENY)
	Raw      string   // сырой ответ LLM-проверяющего (для прозрачности)
}

// EnforceCode — способ 1: детерминированная проверка по стоп-словам (быстро, дёшево).
func EnforceCode(set *InvariantSet, query string) Verdict {
	hit := set.CheckCode(query)
	if len(hit) == 0 {
		return Verdict{Allowed: true}
	}
	var ids, reasons []string
	for _, inv := range hit {
		ids = append(ids, inv.ID)
		reasons = append(reasons, inv.Text)
	}
	return Verdict{
		Allowed:  false,
		Violated: ids,
		Reason:   "Запрос нарушает инвариант(ы): " + strings.Join(reasons, "; "),
		ByCode:   true,
	}
}

// EnforceLLM — способ 2: семантическая проверка запроса моделью.
// Возвращает вердикт ALLOW/DENY + объяснение. Эти способы не взаимоисключают друг друга.
// День 27: проверка инвариантов идёт через сменный Completer (облако или локаль),
// а не напрямую в anthropic.Client. Поведение то же — меняется лишь бэкенд.
func EnforceLLM(ctx context.Context, gen Completer, set *InvariantSet, query string) (Verdict, error) {
	rules := set.Render()
	sys := "Ты — проверяющий. Тебе даны инварианты и запрос пользователя. " +
		"Реши, нарушает ли ВЫПОЛНЕНИЕ запроса хотя бы один инвариант. " +
		"Ответь строго в формате:\nDECISION: ALLOW|DENY\nREASON: <одно предложение, какой инвариант и почему>"
	user := "[ИНВАРИАНТЫ]\n" + rules + "\n[ЗАПРОС]\n" + query

	out, _, err := gen.Complete(ctx, sys, []Msg{{Role: roleUser, Text: user}}, CompleteOpts{MaxTokens: 200})
	if err != nil {
		return Verdict{}, fmt.Errorf("enforce(llm): %w", err)
	}
	decision, reason := parseVerdict(out)
	return Verdict{
		Allowed:  decision == "ALLOW",
		Reason:   reason,
		Decision: decision,
		Raw:      strings.TrimSpace(out),
	}, nil
}

func parseVerdict(s string) (decision, reason string) {
	decision = "ALLOW"
	for _, line := range strings.Split(s, "\n") {
		l := strings.TrimSpace(line)
		up := strings.ToUpper(l)
		if strings.HasPrefix(up, "DECISION:") {
			if strings.Contains(up, "DENY") {
				decision = "DENY"
			} else {
				decision = "ALLOW"
			}
		}
		if strings.HasPrefix(up, "REASON:") {
			reason = strings.TrimSpace(l[len("REASON:"):])
		}
	}
	return decision, reason
}

