// ответить ни на один вопрос о структуре проекта.
//
// Дело не в том, что «надо было закоммитить». Ассистент разработчика обязан видеть
// РАБОЧЕЕ ДЕРЕВО: файл, который ты только что создал и ещё не добавил в индекс, —
// как раз самый интересный для вопроса «что у меня в проекте». Поэтому берём и
// отслеживаемые (--cached), и новые (--others), уважая .gitignore (--exclude-standard),
// и помечаем новые, чтобы модель понимала разницу.
func listFiles(ctx context.Context, repo, path string, limit int) (string, error) {
	if limit <= 0 {
		limit = 200
	}
	pathArgs := []string{}
	if path != "" {
		p, err := safeArg(path)
		if err != nil {
			return "", err
		}
		pathArgs = append(pathArgs, "--", p) // "--" отсекает трактовку пути как флага
	}

	tracked, err := git(ctx, repo, append([]string{"ls-files", "--cached"}, pathArgs...)...)
	if err != nil {
		return "", err
	}
	untracked, err := git(ctx, repo, append([]string{"ls-files", "--others", "--exclude-standard"}, pathArgs...)...)
	if err != nil {
		return "", err
	}

	tr, un := splitNonEmpty(tracked), splitNonEmpty(untracked)

func listFiles(ctx context.Context, repo, path string, limit int) (string, error) {
    // …
	rows := make([]string, 0, len(tr)+len(un))
	rows = append(rows, tr...)
	rows = append(rows, un...)
	if len(rows) == 0 {
		return "файлов: 0 (пусто — проверь путь и .gitignore)", nil
	}
	sort.Strings(rows)

	// Пометку «новый» держим в ШАПКЕ, а не на каждой строке. Первый вариант дописывал
	// «[новый, не в индексе git]» к каждому пути — и на свежем, ещё не закоммиченном
	// каталоге (где новые ВСЕ файлы) блок контекста распух с ~2 КБ до 3.2 КБ чистого
	// шума, который улетал бы в каждый промпт.
	total := len(rows)
	if total > limit {
		rows = rows[:limit]
	}
	head := fmt.Sprintf("файлов: %d (под git: %d, новых — ещё не в индексе: %d)", total, len(tr), len(un))
	if total > limit {
		head += fmt.Sprintf(" — показаны первые %d", limit)
	}
	return head + "\n" + strings.Join(rows, "\n"), nil
}

func diff(ctx context.Context, repo, ref, path string, stat bool) (string, error) {
	args := []string{"diff"}
	if stat {
		args = append(args, "--stat")
	} else {
		args = append(args, "--unified=3")
	}
	if ref != "" {
		r, err := safeArg(ref)
		if err != nil {
			return "", err
		}
		args = append(args, r)
	}
	if path != "" {
		p, err := safeArg(path)
		if err != nil {
			return "", err
		}
		args = append(args, "--", p)
	}
	out, err := git(ctx, repo, args...)
	if err != nil {
		return "", err
	}
	if strings.TrimSpace(out) == "" {
		return "изменений нет (пустой diff)", nil
	}
	return clip(out), nil
}

func gitLog(ctx context.Context, repo string, limit int, path string) (string, error) {
	if limit <= 0 {
		limit = 10
	}
	if limit > 50 {
		limit = 50
	}
	args := []string{"log", "-n", strconv.Itoa(limit), "--date=short",
		"--pretty=format:%h %ad %an — %s"}
	if path != "" {
		p, err := safeArg(path)
		if err != nil {
			return "", err
		}
		args = append(args, "--", p)
	}
	out, err := git(ctx, repo, args...)
	if err != nil {
		return "", err
	}
	if strings.TrimSpace(out) == "" {
		return "история пуста", nil
	}
	return clip(out), nil
}

// git запускает ТОЛЬКО читающие подкоманды. Аргументы передаются вектором в exec —
// никакого shell, значит никакой инъекции через `;` или `$(...)`. Подкоманда всегда
// задаётся НАМИ (белый список ниже), из JSON приходят только ref/path, и они
// проверяются в safeArg.
func git(ctx context.Context, repo string, args ...string) (string, error) {
	if len(args) == 0 || !readOnly[args[0]] {
		return "", fmt.Errorf("подкоманда %q запрещена: сервер работает только на чтение", firstOf(args))
	}
	ctx, cancel := context.WithTimeout(ctx, gitTimeout)
	defer cancel()

	// --no-pager: иначе git на TTY уйдёт в less и повиснет.
	// -c core.quotepath=false: не экранировать кириллицу в путях в \NNN.
	full := append([]string{"--no-pager", "-c", "core.quotepath=false"}, args...)
	cmd := exec.CommandContext(ctx, "git", full...)
	cmd.Dir = repo
	cmd.Env = append(os.Environ(), "GIT_TERMINAL_PROMPT=0") // не спрашивать логин/пароль

	var stderr strings.Builder
	cmd.Stderr = &stderr
	out, err := cmd.Output()
	if err != nil {
		msg := strings.TrimSpace(stderr.String())
		if msg == "" {
			msg = err.Error()
		}
		return "", fmt.Errorf("git %s: %s", strings.Join(args, " "), msg)
	}
	return strings.TrimRight(string(out), "\n"), nil
}

// readOnly — белый список подкоманд. Всё остальное (add/commit/push/checkout/reset/
// clean/config/remote…) недоступно ПО ПОСТРОЕНИЮ, а не по договорённости.
var readOnly = map[string]bool{
	"rev-parse": true,
	"status":    true,
	"ls-files":  true,
	"diff":      true,
	"log":       true,
}

// safeArg — валидация строк, пришедших из JSON от модели. Главная угроза не
// «rm -rf», а то, что аргумент притворится ФЛАГОМ (напр. path="--output=/etc/x"):
// git разберёт его как опцию. Поэтому: ведущий дефис запрещён, набор символов
// ограничен, `..` в пути запрещён.
func safeArg(s string) (string, error) {
	s = strings.TrimSpace(s)
	if s == "" {
		return "", fmt.Errorf("пустой аргумент")
	}
	if strings.HasPrefix(s, "-") {
		return "", fmt.Errorf("аргумент %q начинается с дефиса — запрещено (выглядит как флаг git)", s)
	}
	if strings.Contains(s, "..") && !strings.Contains(s, "...") {
		// git-диапазоны 'a..b'/'a...b' легитимны; выход из каталога '../' — нет.
		if strings.Contains(s, "../") || strings.Contains(s, "/..") {
			return "", fmt.Errorf("выход за пределы репозитория запрещён: %q", s)
		}
	}
	for _, r := range s {
		switch {
		case r >= 'a' && r <= 'z', r >= 'A' && r <= 'Z', r >= '0' && r <= '9':
		case strings.ContainsRune("._/-~^@", r):
		default:
			return "", fmt.Errorf("недопустимый символ %q в аргументе %q", r, s)
		}
	}
	return s, nil
}

// repoRoot ищет корень репозитория от каталога сервера вверх (git сам умеет это
// через rev-parse --show-toplevel). Можно переопределить через -repo или GIT_REPO.
func repoRoot() (string, error) {
	start := sourceDir()
	if len(os.Args) > 2 && os.Args[1] == "-repo" {
		start = os.Args[2]
	} else if v := os.Getenv("GIT_REPO"); v != "" {
		start = v
	}
	ctx, cancel := context.WithTimeout(context.Background(), gitTimeout)
	defer cancel()
	cmd := exec.CommandContext(ctx, "git", "-C", start, "rev-parse", "--show-toplevel")
	out, err := cmd.Output()
	if err != nil {
		return "", fmt.Errorf("git rev-parse в %s: %w", start, err)
	}
	return strings.TrimSpace(string(out)), nil
}

func clip(s string) string {
	if len(s) <= maxOutChars {
		return s
	}
	return s[:maxOutChars] + fmt.Sprintf("\n… [усечено: %d символов из %d]", maxOutChars, len(s))
}

func splitNonEmpty(s string) []string {
	var out []string
	for _, ln := range strings.Split(s, "\n") {
		if strings.TrimSpace(ln) != "" {
			out = append(out, ln)
		}
	}
	return out
}

func firstOf(args []string) string {
	if len(args) == 0 {
		return ""
	}
	return args[0]
}

func sourceDir() string {
	if _, file, _, ok := runtime.Caller(0); ok {
		return filepath.Dir(file)
	}
	return "."
}

func okText(s string) *mcp.CallToolResult {
	return &mcp.CallToolResult{Content: []mcp.Content{&mcp.TextContent{Text: s}}}
}

func errText(err error) *mcp.CallToolResult {
	return &mcp.CallToolResult{IsError: true, Content: []mcp.Content{&mcp.TextContent{Text: "ошибка: " + err.Error()}}}
}

// ProjectSnapshot — то, что мы знаем о проекте БЕЗ участия LLM.
type ProjectSnapshot struct {
	Branch string   // сырой вывод git_branch (ветка, HEAD, upstream, грязность)
	Head   string   // шапка git_files: сколько файлов, из них новых (ещё не в индексе)
	Files  []string // пути в РАБОЧЕМ ДЕРЕВЕ (отслеживаемые + новые), в пределах scope
	Scope  string   // каталог, которым ограничен снимок ("" = весь репозиторий)
	Err    string   // почему снимок не собран (MCP лежит, git не найден…)
}

// fetchProjectSnapshot делает ДВА прямых вызова MCP-тулов. Токены не тратятся:
// это не диалог с моделью, это вызов функции по имени (маршрутизация — день 20).
func fetchProjectSnapshot(ctx context.Context, m *MCPTools, scope string, limit int) ProjectSnapshot {
	ps := ProjectSnapshot{Scope: scope}
	if m == nil {
		ps.Err = "MCP не подключён"
		return ps
	}

	// ВНИМАНИЕ на сигнатуру (баг, пойманный на живом прогоне): MCPTools.Call
	// возвращает (текст, **isError**), а НЕ (текст, ok). В agent.go это видно по
	// имени (`out, isErr := a.mcp.Call(...)`), а все остальные вызывающие просто
	// глотают второе значение в `_`, поэтому неверная трактовка нигде не всплывала.
	// Прочитав его как `ok`, мы разворачивали смысл наизнанку: успешный вызов
	// (isError=false) уходил в ветку ошибки. Симптом был абсурдным — «снимок не
	// собран», и тут же корректный вывод git_branch в тексте ошибки.
	branch, isErr := m.Call(ctx, "git_branch", json.RawMessage(`{}`))
	if isErr || strings.HasPrefix(branch, "ошибка:") {
		ps.Err = "git_branch: " + oneLine(branch, 120)
		return ps
	}
	ps.Branch = strings.TrimSpace(branch)

	files, isErr := m.Call(ctx, "git_files", jsonArgs(map[string]any{"path": scope, "limit": limit}))
	if isErr || strings.HasPrefix(files, "ошибка:") {
		// Ветку получили — этого уже хватает на минимум задания. Список файлов
		// не критичен, поэтому не роняем снимок целиком.

func fetchProjectSnapshot(ctx context.Context, m *MCPTools, scope string, limit int) ProjectSnapshot {
    // …
		return ps
	}
	for i, ln := range strings.Split(files, "\n") {
		ln = strings.TrimSpace(ln)
		if i == 0 && strings.HasPrefix(ln, "файлов:") {
			ps.Head = ln // шапка со счётчиками — она информативна, не выбрасываем
			continue
		}
		if ln != "" {
			ps.Files = append(ps.Files, ln)
		}
	}
	return ps
}

// renderProjectContext — блок, который уходит в промпт. Задание просит, чтобы
// /help отвечал «на вопросы о СТРУКТУРЕ проекта», поэтому дерево файлов — не
// украшение, а основной материал ответа. Держим его компактным: группируем по
// каталогу, а не вываливаем 60 путей плоским списком.
func renderProjectContext(ps ProjectSnapshot) string {
	if !ps.OK() {
		return ""
	}
	var b strings.Builder
	b.WriteString(ps.Branch)
	if len(ps.Files) == 0 {
		return b.String()
	}

	scope := ps.Scope
	if scope == "" {
		scope = "(весь репозиторий)"
	}
	fmt.Fprintf(&b, "\n\nструктура %s — %s", scope, ps.Head)

	byDir := map[string][]string{}
	for _, f := range ps.Files {
		rel := strings.TrimPrefix(f, ps.Scope+"/")
		dir := "."
		name := rel
		if i := strings.LastIndex(rel, "/"); i >= 0 {
			dir, name = rel[:i], rel[i+1:]
		}
		byDir[dir] = append(byDir[dir], name)
	}
	dirs := make([]string, 0, len(byDir))
	for d := range byDir {
		dirs = append(dirs, d)
	}
	sort.Strings(dirs)
	for _, d := range dirs {
		names := byDir[d]
		sort.Strings(names)
		fmt.Fprintf(&b, "\n  %s/  (%d): %s", d, len(names), strings.Join(names, ", "))
	}
	return b.String()
}

// helpReply — конвейер /help. Это НЕ groundedReply: у него другое поведение на
// пороге «не знаю», и вот почему.
//
// groundedReply (день 24) при best < threshold сразу отвечает «не знаю» — он знает
// ровно один источник, документацию. Но /help знает два. Вопрос «какая сейчас
// ветка?» по документации не находит НИЧЕГО (и правильно: этого нет ни в одном
// README) → старый порог убил бы ответ, хотя ответ у нас на руках, в пре-фетче.
//
// Поэтому порог здесь означает не «не знаю», а «документация не помогла»:
//   - нет чанков И нет контекста проекта → честное «не знаю»;
//   - нет чанков, но контекст проекта есть → отвечаем ТОЛЬКО по нему (sources пуст);
//   - чанки есть → обычный grounded-ответ с цитатами + контекст проекта сверху.
