    // …
					"а живой контекст проекта недоступен (MCP не подключён).",
			}, hits, tr, nil
		}
		hits = nil // отвечаем по живому контексту, цитировать нечего
	}

	rep, err := a.groundedAnswer(ctx, cfg.Model, query, hits)
	if err != nil {
