func sourceHits23(expected []string, hits []ragcore.Hit) (got, total int) {
	total = len(expected)
	if total == 0 {
		return 0, 0
	}
	have := map[string]bool{}
	for _, h := range hits {
		have[h.Chunk.Source] = true
	}
	for _, e := range expected {
		for src := range have {
			if strings.Contains(src, e) || strings.Contains(e, src) {
				got++
				break
			}
		}
	}
	return got, total
}

func topSrc(hits []ragcore.Hit) string {
	if len(hits) == 0 {
		return "(пусто)"
	}
	parts := make([]string, 0, len(hits))
	for _, h := range hits {
		parts = append(parts, fmt.Sprintf("%s(%.2f)", h.Chunk.Source, h.Score))
	}
	return strings.Join(parts, ", ")
}

func frac(a, b int) string {
	if b == 0 {
		return "—"
	}
	return fmt.Sprintf("%d/%d (%.0f%%)", a, b, 100*float64(a)/float64(b))
}

// Package ragcore — единая точка правды формата RAG-индекса дня 21/22.
// Здесь живут тип чанка, индекс, эмбеддер и поиск. И утилита индексации
// (ragindex, cmd), и накопительный агент импортируют этот пакет — формат
// объявлен один раз, рассинхрон между продьюсером и консьюмером невозможен.
package ragcore

// Embedder — абстракция эмбеддера. Методы РАЗДЕЛЕНЫ на документ и запрос:
// инструктивные модели (nomic-embed-text, E5, BGE…) обучены с разными
// префиксами задачи для индексируемого текста и поискового запроса, и без
// этого разделения качество поиска резко падает (один обзорный документ
// начинает матчить все запросы). См. OllamaEmbedder.
type Embedder interface {
	EmbedDocument(ctx context.Context, text string) ([]float32, error)
	EmbedQuery(ctx context.Context, text string) ([]float32, error)
	Name() string
}

// OllamaEmbedder — локальный эмбеддер через HTTP API Ollama (без SDK, чистый net/http).
//
//	POST {baseURL}/api/embeddings  body {"model":..,"prompt":..} -> {"embedding":[..]}
//
// Для nomic-embed-text вектор 768-мерный. Данные не покидают машину (см. «Why Ollama»).
//
// ВАЖНО: nomic-embed-text обучен с префиксами задачи. Документы индексируются с
// "search_document: ", запрос — с "search_query: ". Префиксы асимметричны намеренно:
// без них пространство «схлопывается» и длинный обзорный текст матчит всё подряд.
type OllamaEmbedder struct {
	BaseURL     string
	Model       string
	MaxChars    int    // макс. длина входа в рунах: защита от лимита контекста модели (0 = без лимита)
	DocPrefix   string // префикс для индексируемых чанков (nomic: "search_document: ")
	QueryPrefix string // префикс для поискового запроса (nomic: "search_query: ")
	Truncated   int    // сколько входов было усечено (для отчёта)
	http        *http.Client
}

func NewOllamaEmbedder(baseURL, model string) *OllamaEmbedder {
	if baseURL == "" {
		baseURL = "http://localhost:11434"
	}
	if model == "" {
		model = "nomic-embed-text"
	}
	return &OllamaEmbedder{
		BaseURL:     baseURL,
		Model:       model,
		MaxChars:    1800, // у nomic-embed-text контекст 2048 токенов; токенов ≤ символов, 1800 — безопасно
		DocPrefix:   "search_document: ",
		QueryPrefix: "search_query: ",
		http:        &http.Client{Timeout: 60 * time.Second},
	}
}

// EmbedDocument эмбеддит индексируемый чанк (префикс search_document:).
func (o *OllamaEmbedder) EmbedDocument(ctx context.Context, text string) ([]float32, error) {
	return o.embed(ctx, o.DocPrefix, text)
}

// EmbedQuery эмбеддит поисковый запрос (префикс search_query:).
func (o *OllamaEmbedder) EmbedQuery(ctx context.Context, text string) ([]float32, error) {
	return o.embed(ctx, o.QueryPrefix, text)
}

func (o *OllamaEmbedder) embed(ctx context.Context, prefix, text string) ([]float32, error) {
	// Усекаем СОДЕРЖИМОЕ (не префикс) под лимит контекста модели.
	if t, cut := clipRunes(text, o.MaxChars); cut {
		text = t
		o.Truncated++
	}
	body, _ := json.Marshal(map[string]string{"model": o.Model, "prompt": prefix + text})
	req, err := http.NewRequestWithContext(ctx, http.MethodPost, o.BaseURL+"/api/embeddings", bytes.NewReader(body))
	if err != nil {
		return nil, err
	}
	req.Header.Set("Content-Type", "application/json")

	res, err := o.http.Do(req)
	if err != nil {
		return nil, fmt.Errorf("ollama недоступен: %w (запущен ли `ollama serve`, есть ли `ollama pull %s`?)", err, o.Model)
	}
	defer res.Body.Close()
	if res.StatusCode != http.StatusOK {
		return nil, fmt.Errorf("ollama вернул статус %d", res.StatusCode)
	}

	var out struct {
		Embedding []float64 `json:"embedding"`
	}
	if err := json.NewDecoder(res.Body).Decode(&out); err != nil {
		return nil, err
	}
	if len(out.Embedding) == 0 {
		return nil, fmt.Errorf("ollama: пустой вектор (модель %q вернула 0 чисел)", o.Model)
	}
	return l2normalize(out.Embedding), nil
}

// clipRunes усекает строку до max рун; возвращает признак усечения.
func clipRunes(s string, max int) (string, bool) {
	if max <= 0 {
		return s, false
	}
	r := []rune(s)
	if len(r) <= max {
		return s, false
	}
	return string(r[:max]), true
}

// l2normalize приводит вектор к единичной длине, поэтому косинус сводится к
// скалярному произведению (в лекции упрощённо «делить на макс»; для cosine
// корректна именно L2-норма).
func l2normalize(v []float64) []float32 {
	var sum float64
	for _, x := range v {
		sum += x * x
	}
	norm := math.Sqrt(sum)
	out := make([]float32, len(v))
	if norm == 0 {
		for i, x := range v {
			out[i] = float32(x)
		}
		return out
	}
	for i, x := range v {
		out[i] = float32(x / norm)
	}
	return out
}

// Chunk — единица индексации с метаданными (усиление задания дня 21):
// source, file (title), section, chunk_id — на КАЖДЫЙ чанк.
type Chunk struct {
	ID      string    `json:"chunk_id"` // уникальный id чанка
	Source  string    `json:"source"`   // относительный путь файла
	File    string    `json:"file"`     // имя файла (title/file)
	Section string    `json:"section"`  // раздел: заголовок .md / имя декларации .go / part N
	Text    string    `json:"text"`
	Tokens  int       `json:"tokens"`           // приближённый размер (слов)
	Vector  []float32 `json:"vector,omitempty"` // L2-нормированный эмбеддинг (пусто в -dry-run)
}

// Index — локальный индекс: метаданные сборки + чанки с векторами. Хранится в JSON.
// Это контракт между продьюсером (ragindex) и консьюмером (агент): оба используют
// один и тот же тип из ragcore.
type Index struct {
	Model     string  `json:"model"`
	Dim       int     `json:"dim"`
	Strategy  string  `json:"strategy"`
	ChunkSize int     `json:"chunk_size,omitempty"`
	Overlap   int     `json:"overlap,omitempty"`
	Chunks    []Chunk `json:"chunks"`
}

// EmbedAll прогоняет чанки через эмбеддер и заполняет векторы (+ Dim/Model).
func (idx *Index) EmbedAll(ctx context.Context, e Embedder, chunks []Chunk) error {
	idx.Model = e.Name()
	idx.Chunks = make([]Chunk, len(chunks))
	for i, c := range chunks {
		vec, err := e.EmbedDocument(ctx, c.Text)
		if err != nil {
			return fmt.Errorf("чанк %s: %w", c.ID, err)
		}
		if idx.Dim == 0 {
			idx.Dim = len(vec)
		}
		c.Vector = vec
		idx.Chunks[i] = c
		fmt.Printf("\r  эмбеддинг %d/%d", i+1, len(chunks))
	}
	fmt.Println()
	return nil
}

// Save пишет индекс в JSON атомарно (tmp + rename).
func (idx *Index) Save(path string) error {
	data, err := json.MarshalIndent(idx, "", "  ")
	if err != nil {
		return err
	}
	tmp := path + ".tmp"
	if err := os.WriteFile(tmp, data, 0o644); err != nil {
		return err
	}
	return os.Rename(tmp, path)
}

// LoadIndex читает индекс из JSON (его зовёт и агент дня 22, и будущий MCP-тул поиска).
func LoadIndex(path string) (*Index, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	var idx Index
	if err := json.Unmarshal(data, &idx); err != nil {
		return nil, err
	}
	return &idx, nil
}

// Hit — результат поиска: чанк + косинусная близость к запросу.
type Hit struct {
	Chunk Chunk
	Score float64
}

// Search — семантический поиск top-k по косинусной близости. Векторы L2-нормированы,
// поэтому косинус = скалярное произведение. Bi-encoder / первый этап отбора;
// реранкинг cross-encoder'ом — отдельный будущий день.
func (idx *Index) Search(ctx context.Context, e Embedder, query string, k int) ([]Hit, error) {
	q, err := e.EmbedQuery(ctx, query)
	if err != nil {
		return nil, err
	}
	hits := make([]Hit, 0, len(idx.Chunks))
	for _, c := range idx.Chunks {
		hits = append(hits, Hit{Chunk: c, Score: dot(q, c.Vector)})
	}
	sort.Slice(hits, func(i, j int) bool { return hits[i].Score > hits[j].Score })
	if k > 0 && len(hits) > k {
		hits = hits[:k]
	}
	return hits, nil
}

func dot(a, b []float32) float64 {
	n := len(a)
	if len(b) < n {
		n = len(b)
	}
	var s float64
	for i := 0; i < n; i++ {
		s += float64(a[i]) * float64(b[i])
	}
	return s
}

// FilterThreshold отсекает кандидатов со score ниже порога (задание: «порог
// отсечения нерелевантных результатов»). Если порог <= 0 — фильтр не применяется.
func FilterThreshold(hits []Hit, min float64) []Hit {
	if min <= 0 {
		return hits
	}
	out := make([]Hit, 0, len(hits))
	for _, h := range hits {
		if h.Score >= min {
			out = append(out, h)
		}
	}
	return out
}

// MMR (Maximal Marginal Relevance) переупорядочивает кандидатов, балансируя
// релевантность запросу и НЕизбыточность: на каждом шаге берётся кандидат с
// максимумом  lambda*rel - (1-lambda)*max_sim_c_уже_выбранными.
// Убирает near-дубли (в т.ч. несколько похожих чанков одного файла), поднимает
// разнообразие источников. Использует косинус между векторами чанков (векторы
// L2-нормированы ⇒ косинус = скалярное произведение).
//
//	lambda=1   → чистая релевантность (MMR выключен),
//	lambda~0.7 → лёгкая диверсификация (разумный дефолт),
//	lambda=0   → максимум разнообразия.
func MMR(hits []Hit, lambda float64, k int) []Hit {
	if k <= 0 || k > len(hits) {
		k = len(hits)
	}
	if lambda >= 1 || len(hits) <= 1 {
		out := append([]Hit(nil), hits...)
		sort.SliceStable(out, func(i, j int) bool { return out[i].Score > out[j].Score })
		if k < len(out) {
			out = out[:k]
		}
		return out
	}

	remaining := append([]Hit(nil), hits...)
	selected := make([]Hit, 0, k)
	for len(selected) < k && len(remaining) > 0 {
		bestIdx, bestVal := 0, -1e18
		for i, h := range remaining {
			// максимум сходства с уже выбранными
			var maxSim float64
			for _, s := range selected {
				if sim := dot(h.Chunk.Vector, s.Chunk.Vector); sim > maxSim {
					maxSim = sim
				}
			}
			val := lambda*h.Score - (1-lambda)*maxSim
			if val > bestVal {
				bestVal, bestIdx = val, i
			}
		}
		selected = append(selected, remaining[bestIdx])

func MMR(hits []Hit, lambda float64, k int) []Hit {
    // …
		remaining = append(remaining[:bestIdx], remaining[bestIdx+1:]...)
	}
	return selected
}

// UniqueSources считает число различных файлов-источников среди хитов
// (метрика разнообразия выдачи для отчёта до/после MMR).
func UniqueSources(hits []Hit) int {
	seen := map[string]bool{}
	for _, h := range hits {
		seen[h.Chunk.Source] = true
	}
	return len(seen)
}

