// gatherReviewContext строит RAG-контекст: под каждый изменённый файл — свой запрос
// к корпусу. Дедуплицирует чанки между файлами (смежные файлы часто тянут одно и то же).
func (a *Agent) gatherReviewContext(ctx context.Context, r *Retriever, files []FileDiff, cfg ReviewConfig) (string, []string) {
	perFile := cfg.Rerank
	perFile.TopK = cfg.RAGPerFile

	seen := map[string]bool{}
	var blocks []string
	var sources []string

	for _, f := range files {
		path := f.Path
		if path == "" {
			path = f.OldPath
		}
		// Запрос: путь + первые добавленные строки. Путь ловит доки/конвенции по файлу,
		// добавленные строки — смежный код по смыслу изменения.
		query := "конвенции и связанный код для " + path
		if len(f.Added) > 0 {
			query += "\n" + strings.Join(f.Added[:min(len(f.Added), 12)], "\n")
		}

		hits, _, err := retrieveAdvanced(ctx, a, r, query, perFile)
		if err != nil || len(hits) == 0 {
			continue
		}
		for _, h := range hits {
			if seen[h.Chunk.ID] {
				continue
			}
			seen[h.Chunk.ID] = true
			sources = append(sources, fmt.Sprintf("%s · %s", h.Chunk.Source, h.Chunk.Section))
			blocks = append(blocks, fmt.Sprintf("[%s · %s]\n%s", h.Chunk.Source, h.Chunk.Section, h.Chunk.Text))
		}
	}
	if len(blocks) == 0 {
		return "(в документации и коде проекта не нашлось релевантного контекста)", nil
	}
	return strings.Join(blocks, "\n\n"), sources
}

func buildReviewPrompt(files []FileDiff, ragCtx string, maxDiff int) string {
	var b strings.Builder
	b.WriteString("КОНТЕКСТ ПРОЕКТА (документация + код из RAG):\n")
	b.WriteString(ragCtx)
	b.WriteString("\n\n===\n\nDIFF ПУЛ-РЕКВЕСТА:\n")

	var diffB strings.Builder
	for _, f := range files {
		path := f.Path
		if path == "" {
			path = f.OldPath
		}
		tag := "изменён"
		switch {
		case f.IsNew:
			tag = "новый файл"
		case f.IsDeleted:
			tag = "удалён"
		}
		fmt.Fprintf(&diffB, "\n--- %s (%s, +%d/-%d) ---\n%s\n", path, tag, len(f.Added), len(f.Removed), f.Hunk)
	}
	diff := diffB.String()
	if len([]rune(diff)) > maxDiff {
		diff = string([]rune(diff)[:maxDiff]) + "\n… [diff усечён по лимиту промпта]"
	}
	b.WriteString(diff)
	return b.String()
}

// parseReviewJSON терпимо разбирает ответ модели: снимает ```-обёртки, вычленяет
// объект по фигурным скобкам (модель иногда добавляет преамбулу).
func parseReviewJSON(s string) (Review, error) {
	s = strings.TrimSpace(s)
	s = strings.TrimPrefix(s, "```json")
	s = strings.TrimPrefix(s, "```")
	s = strings.TrimSuffix(s, "```")
	if i := strings.IndexByte(s, '{'); i > 0 {
		s = s[i:]
	}
	if j := strings.LastIndexByte(s, '}'); j >= 0 {
		s = s[:j+1]
	}
	var rev Review
	if err := json.Unmarshal([]byte(strings.TrimSpace(s)), &rev); err != nil {
		return Review{}, err
	}
	return rev, nil
}

// renderReviewMarkdown — ревью в виде markdown-коммента для PR.
func renderReviewMarkdown(rev Review, changed []string) string {
	var b strings.Builder
	b.WriteString("## 🤖 AI-ревью\n\n")
	if rev.Summary != "" {
		b.WriteString(rev.Summary + "\n\n")
	}

	if len(rev.Findings) == 0 {
		b.WriteString("_Замечаний нет._\n")
	} else {
		bugs, arch, sug := groupBySeverity(rev.Findings)
		writeGroup(&b, "🔴 Потенциальные баги", bugs)
		writeGroup(&b, "🟠 Архитектурные проблемы", arch)
		writeGroup(&b, "🟡 Рекомендации", sug)
	}

	if len(changed) > 0 {
		fmt.Fprintf(&b, "\n<sub>Проверено файлов: %d · %s</sub>\n", len(changed), strings.Join(changed, ", "))
	}
	if len(rev.Sources) > 0 {
		fmt.Fprintf(&b, "<sub>Контекст из проекта: %s</sub>\n", strings.Join(dedupe(rev.Sources), "; "))
	}
	return b.String()
}

func groupBySeverity(fs []ReviewFinding) (bugs, arch, sug []ReviewFinding) {
	for _, f := range fs {
		switch f.Severity {
		case "bug":
			bugs = append(bugs, f)
		case "architecture":
			arch = append(arch, f)
		default:
			sug = append(sug, f)
		}
	}
	return
}

func writeGroup(b *strings.Builder, title string, fs []ReviewFinding) {
	if len(fs) == 0 {
		return
	}
	fmt.Fprintf(b, "### %s\n\n", title)
	for _, f := range fs {
		if f.File != "" {
			fmt.Fprintf(b, "- **%s** (`%s`): %s\n", f.Title, f.File, f.Detail)
		} else {
			fmt.Fprintf(b, "- **%s**: %s\n", f.Title, f.Detail)
		}
	}
	b.WriteString("\n")
}

func dedupe(ss []string) []string {
	seen := map[string]bool{}
	var out []string
	for _, s := range ss {
		if !seen[s] {
			seen[s] = true
			out = append(out, s)
		}
	}
	return out
}

func min(a, b int) int {
	if a < b {
		return a
	}
	return b
}

import (
	"bufio"
	"strings"
)

// parseDiff разбирает unified diff в срез FileDiff, по одному на файл.
func parseDiff(diff string) []FileDiff {
	var files []FileDiff
	var cur *FileDiff
	var hunk strings.Builder

	flush := func() {
		if cur == nil {
			return
		}
		cur.Hunk = strings.TrimRight(hunk.String(), "\n")
		cur.addedCount = len(cur.Added)
		files = append(files, *cur)
		cur = nil
		hunk.Reset()
	}

	sc := bufio.NewScanner(strings.NewReader(diff))
	sc.Buffer(make([]byte, 0, 64*1024), 4*1024*1024) // крупные ханки не должны ронять сканер

	for sc.Scan() {
		line := sc.Text()
		switch {
		case strings.HasPrefix(line, "diff --git "):
			flush()
			cur = &FileDiff{}
			// "diff --git a/path b/path" — пути берём отсюда как запасной вариант,
			// точные придут из +++/--- ниже.
			if a, b, ok := parseGitHeader(line); ok {
				cur.OldPath, cur.Path = a, b
			}
		case cur == nil:
			// шапка до первого файла (commit message и т.п.) — пропускаем
			continue
		case strings.HasPrefix(line, "new file"):
			cur.IsNew = true
		case strings.HasPrefix(line, "deleted file"):
			cur.IsDeleted = true
		case strings.HasPrefix(line, "--- "):
			if p := pathFromMarker(line, "--- "); p != "" {
				cur.OldPath = p
			}
		case strings.HasPrefix(line, "+++ "):
			if p := pathFromMarker(line, "+++ "); p != "" {
				cur.Path = p
			}
		case strings.HasPrefix(line, "@@"):
			hunk.WriteString(line + "\n")
		case strings.HasPrefix(line, "+"):

func parseDiff(diff string) []FileDiff {
    // …
			cur.Added = append(cur.Added, strings.TrimPrefix(line, "+"))
			hunk.WriteString(line + "\n")
		case strings.HasPrefix(line, "-"):
			cur.Removed = append(cur.Removed, strings.TrimPrefix(line, "-"))
			hunk.WriteString(line + "\n")
		default:
			// контекстная строка (' ') или прочее — сохраняем в ханк для читаемости
			if strings.TrimSpace(line) != "" {
				hunk.WriteString(line + "\n")
			}
		}
	}
	flush()
	return files
}

// parseGitHeader вытаскивает пути из "diff --git a/x b/y".
func parseGitHeader(line string) (a, b string, ok bool) {
	rest := strings.TrimPrefix(line, "diff --git ")
	// Простейший разбор по " b/" — путей с пробелами в нашем корпусе нет.
	i := strings.Index(rest, " b/")
	if i < 0 {
		return "", "", false
	}
	a = strings.TrimPrefix(rest[:i], "a/")
	b = strings.TrimPrefix(rest[i+1:], "b/")
	return a, b, true
}

// pathFromMarker разбирает "+++ b/path" / "--- a/path"; "/dev/null" → "".
func pathFromMarker(line, prefix string) string {
	p := strings.TrimSpace(strings.TrimPrefix(line, prefix))
	if p == "/dev/null" {
		return ""
	}
	p = strings.TrimPrefix(p, "a/")
	p = strings.TrimPrefix(p, "b/")
	// у +++/--- иногда есть табличный таймстамп после \t
	if i := strings.IndexByte(p, '\t'); i >= 0 {
		p = p[:i]
	}
	return p
}

// changedPaths — уникальные пути затронутых файлов (для RAG-запросов и заголовка ревью).
func changedPaths(files []FileDiff) []string {
	seen := map[string]bool{}
	var out []string
	for _, f := range files {
		p := f.Path
		if p == "" {
			p = f.OldPath
		}
		if p != "" && !seen[p] {
			seen[p] = true
			out = append(out, p)
		}
	}
	return out
}

// ReviewInput — откуда взять diff и куда (если куда-то) постить.
type ReviewInput struct {
	Diff     string // сам diff
	Repo     string // "owner/repo" (для постинга в GitHub)
	PRNumber int    // номер PR
	Token    string // GITHUB_TOKEN
	DryRun   bool   // true = только печать, без постинга
	StrictCI bool   // true = ненулевой код выхода при наличии bug/architecture
	APIBase  string // база GitHub API (для тестов; по умолчанию api.github.com)
}

// runReview32 — локальный/демо-режим: diff из -diff-file или stdin, ревью в терминал.
func runReview32(ctx context.Context, a *Agent, r *Retriever, cfg ReviewConfig, diffPath string) error {
	diff, err := readDiff(diffPath)
	if err != nil {
		return err
	}
	if strings.TrimSpace(diff) == "" {
		return fmt.Errorf("пустой diff (укажи -diff-file или подай diff в stdin)")
	}

	ragBanner(0, "АВТОМАТИЗАЦИЯ РЕВЬЮ КОДА · день 32")
	fmt.Println("Пайплайн: diff → RAG (документация + код проекта) → ревью.")
	files := parseDiff(diff)
	fmt.Printf("Файлов в diff: %d · %s\n", len(files), strings.Join(changedPaths(files), ", "))
	fmt.Printf("Индекс корпуса: %s\n\n", r.Info())

	rev, err := reviewPR(ctx, a, r, diff, cfg)
	if err != nil {
		return err
	}

	md := renderReviewMarkdown(rev, changedPaths(files))
	fmt.Println(md)
	fmt.Printf("\n[usage] вход %d · выход %d токенов · блокеров: %v\n",
		rev.rawUsage.Input, rev.rawUsage.Output, rev.HasBlockers())
	return nil
}

// runReviewCI — реактивный режим внутри GitHub Action: diff из события, ревью
// комментом в PR. Возвращает ошибку, если StrictCI и есть блокеры.
func runReviewCI(ctx context.Context, a *Agent, r *Retriever, cfg ReviewConfig, in ReviewInput) error {
	files := parseDiff(in.Diff)
	if len(files) == 0 {
		fmt.Println("diff пуст — ревьюить нечего, выходим без коммента")
		return nil
	}
	rev, err := reviewPR(ctx, a, r, in.Diff, cfg)
	if err != nil {
		return err
	}
	md := renderReviewMarkdown(rev, changedPaths(files))

	if in.DryRun || in.Token == "" || in.Repo == "" || in.PRNumber == 0 {
		fmt.Println("[dry-run] коммент не постится, вот его содержимое:")
		fmt.Println()
		fmt.Println(md)
	} else {
		if err := postPRComment(ctx, in, md); err != nil {
			return fmt.Errorf("постинг коммента: %w", err)
		}
		fmt.Printf("Ревью опубликовано в %s#%d\n", in.Repo, in.PRNumber)
	}

	if in.StrictCI && rev.HasBlockers() {
		return fmt.Errorf("ревью нашло блокеры (bug/architecture) — проваливаем проверку CI")
	}
	return nil
}

// postPRComment публикует коммент в PR через GitHub REST API.
// PR-комменты создаются через issues endpoint (PR — это тоже issue).
func postPRComment(ctx context.Context, in ReviewInput, body string) error {
	base := in.APIBase
	if base == "" {
		base = "https://api.github.com"
	}
	url := fmt.Sprintf("%s/repos/%s/issues/%d/comments", base, in.Repo, in.PRNumber)
	payload, _ := json.Marshal(map[string]string{"body": body})

	req, err := http.NewRequestWithContext(ctx, http.MethodPost, url, bytes.NewReader(payload))
	if err != nil {
		return err
	}
	req.Header.Set("Authorization", "Bearer "+in.Token)
	req.Header.Set("Accept", "application/vnd.github+json")
	req.Header.Set("X-GitHub-Api-Version", "2022-11-28")
	req.Header.Set("Content-Type", "application/json")

	client := &http.Client{Timeout: 30 * time.Second}
	resp, err := client.Do(req)
	if err != nil {
		return err
	}
	defer resp.Body.Close()
	if resp.StatusCode >= 300 {
		b, _ := io.ReadAll(resp.Body)
		return fmt.Errorf("GitHub API %d: %s", resp.StatusCode, oneLine(string(b), 200))
	}
	return nil
}

// readDiff читает diff из файла, а если путь пуст — из stdin.
func readDiff(path string) (string, error) {
	if path != "" {
		b, err := os.ReadFile(path)
		if err != nil {
			return "", fmt.Errorf("чтение diff-файла: %w", err)
		}
		return string(b), nil
	}
	// stdin (например: git diff main...HEAD | ... -review32)
	stat, _ := os.Stdin.Stat()
	if (stat.Mode() & os.ModeCharDevice) != 0 {
		return "", nil // это терминал, данных на входе нет
	}
	b, err := io.ReadAll(os.Stdin)
	if err != nil {
		return "", err
	}
	return string(b), nil
}

// reviewInputFromEnv собирает ReviewInput из окружения GitHub Action.
// Diff берётся из готового файла (Action его формирует шагом раньше — см. .github/workflows).
func reviewInputFromEnv(diffPath string, dryRun, strict bool) (ReviewInput, error) {
	diff, err := readDiff(diffPath)
	if err != nil {
		return ReviewInput{}, err
	}
	in := ReviewInput{
		Diff:     diff,
		Repo:     os.Getenv("GITHUB_REPOSITORY"), // "owner/repo", даёт Action
		Token:    os.Getenv("GITHUB_TOKEN"),      // secrets.GITHUB_TOKEN
		DryRun:   dryRun,
		StrictCI: strict,
	}
	if n := os.Getenv("PR_NUMBER"); n != "" {
		in.PRNumber, _ = strconv.Atoi(n)
	}
	return in, nil
}

// serveConfig — параметры сервиса.
type serveConfig struct {
	Addr          string // адрес прослушивания, напр. ":8080" (0.0.0.0 → доступ по сети)
	APIKey        string // Bearer-ключ; пусто = открытый сервис (предупреждаем)
	RateRPM       int    // лимит запросов в минуту на клиента (IP)
	MaxCtx        int    // потолок контекстного окна (num_ctx)
	MaxConcurrent int    // одновременных генераций (стабильность)
}

// runServe30 поднимает сервис и блокируется до отмены ctx (Ctrl+C).
// buildService собирает сервер и http.Server (общее для обычного и демо-режима).
func buildService(llm *LocalLLM, cfg serveConfig) (*server, *http.Server) {
	srv := &server{
		llm: llm, cfg: cfg,
		lim: newIPLimiter(cfg.RateRPM),
		sem: make(chan struct{}, max1(cfg.MaxConcurrent)),
	}
	mux := http.NewServeMux()
	mux.HandleFunc("/health", srv.handleHealth)                      // без ключа: liveness
	mux.HandleFunc("/v1/models", srv.auth(srv.handleModels))         // OpenAI: список моделей
	mux.HandleFunc("/v1/chat/completions", srv.auth(srv.handleChat)) // OpenAI: чат
	return srv, &http.Server{Addr: cfg.Addr, Handler: mux, ReadHeaderTimeout: 10 * time.Second}
}

